import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Regolare la saturazione richiede solo pochi minuti. Carichi la foto, trascini un cursore, controlli i colori e scarichi la versione più vivida.</p>\n<p>Questa guida pratica ti accompagna in tutto il procedimento, passo passo. Copre il cursore, i preset rapidi, i toni della pelle e le impostazioni di esportazione che mantengono naturali i colori.</p>\n<p>Alla fine saprai sistemare un paesaggio spento, attenuare una foto pacchiana o trasformare un ritratto a colori in un bianco e nero pulito su qualsiasi dispositivo. Conserva la foto originale finché non hai controllato il risultato.</p>\n<h2 id=\"before-you-start\">Prima di iniziare: valuta i colori</h2>\n<p>Guarda la foto prima di aprire lo strumento. I colori sono spenti, vividi o pacchiani? La risposta ti dice in quale direzione spostare il cursore.</p>\n<p>Una foto spenta ha bisogno di una spinta positiva, del 10-25%. Una pacchiana ha bisogno di uno spostamento negativo, per attenuare i colori e riportarli verso il naturale.</p>\n<p>Controlla se la foto è anche troppo scura o troppo piatta. Una foto spenta e scura ha bisogno prima di luminosità, perché la saturazione da sola non può sistemare il livello.</p>\n<p>Apri lo strumento <a href=\"/it/regola-saturazione-immagine/\">Regola saturazione immagine</a> nel browser. Tutto funziona in locale, quindi la tua foto non viene mai caricata su un server.</p>\n<h2 id=\"step-by-step\">Regola la saturazione in cinque passaggi</h2>\n<p>Il procedimento è lo stesso per una foto, uno screenshot o un’immagine scansionata. Carica, regola, controlla i colori, esporta e verifica il file scaricato.</p>\n<p>Prenditi il tempo necessario per il cursore. Piccoli spostamenti fanno una grande differenza, e l’anteprima ti mostra esattamente quando i colori sembrano giusti.</p>\n<ol>\n<li>Carica l’immagine trascinandola nella zona di caricamento, scegliendola dal dispositivo oppure incollando uno screenshot con Ctrl+V.</li>\n<li>Trascina il cursore Livello di saturazione a destra per potenziare i colori o a sinistra per attenuarli, guardando l’anteprima in tempo reale.</li>\n<li>Prova un preset rapido come Attenuato, Bianco e nero o Iper per un test in un clic, poi rifinisci con il cursore.</li>\n<li>Controlla i toni della pelle, il fogliame e il cielo a dimensione intera per confermare che nessun colore sembri artificiale.</li>\n<li>Scegli il formato di esportazione e la qualità, poi clicca Scarica per salvare l’immagine modificata.</li>\n</ol>\n<p>Apri il file scaricato una volta prima di usarlo. Conferma che i colori sembrino naturali e vividi, senza diventare neon o arancioni.</p>\n<h2 id=\"using-the-slider\">Usare il cursore della saturazione</h2>\n<p>Il cursore va da −100% a +100%, con lo zero che significa nessun cambiamento. Spostandolo a destra si potenziano i colori, spostandolo a sinistra li si scarica.</p>\n<p>Trascina lentamente e guarda l’anteprima. L’aggiornamento in tempo reale mostra esattamente come rispondono i colori, così puoi fermarti nel punto in cui la foto sembra naturale.</p>\n<p>I piccoli spostamenti sono meglio di quelli grandi. Una variazione del 10-25% basta spesso, e spostamenti più grandi fanno sembrare i colori artificiali in fretta.</p>\n<p>Lo strumento mostra la tua foto a +25% subito dopo il caricamento. Questo punto di partenza ti dà subito un’idea di come appare una spinta moderata di saturazione.</p>\n<h2 id=\"using-quick-presets\">Usare i preset rapidi</h2>\n<p>Lo strumento include preset in un clic che applicano valori comuni di saturazione all’istante. Sono un modo veloce per provare aspetti diversi senza trascinare il cursore.</p>\n<p>Attenuato a −40% ammorbidisce i colori per un aspetto calmo ed elegante. Bianco e nero a −100% toglie tutto il colore per un’immagine in bianco e nero.</p>\n<p>Iper a +90% spinge i colori al limite. Va bene per poster e grafiche stilizzate, ma raramente va bene per la fotografia naturale.</p>\n<p>Clicca un preset e guarda l’anteprima. Se il risultato è vicino ma non del tutto giusto, rifinisci con il cursore da quel punto.</p>\n<h2 id=\"boosting-a-dull-photo\">Potenziare una foto spenta</h2>\n<p>Carica la foto spenta e trascina il cursore a +20%. Controlla l’anteprima: i colori dovrebbero sembrare più ricchi, con i verdi più profondi e i cieli più blu, senza sembrare finti.</p>\n<p>Se la foto è ancora spenta, aumenta il cursore a piccoli passi del 5%. Ogni passo aggiunge un po’ di vividezza in più, e l’anteprima mostra quando fermarsi.</p>\n<p>Guarda il fogliame mentre procedi. Erba e foglie diventano neon per prime, e un paesaggio con campi verdi luminosi sembra artificiale.</p>\n<p>Se dopo la spinta la foto sembra pacchiana, abbassa il cursore del 5%. Una piccola riduzione spesso ripristina l’aspetto naturale senza far perdere la vividezza.</p>\n<h2 id=\"muting-a-harsh-photo\">Attenuare una foto dura e pacchiana</h2>\n<p>Trascina il cursore a sinistra per una foto i cui colori sono troppo forti. Valori negativi come −20% o −40% ammorbidiscono la tavolozza in un aspetto più calmo.</p>\n<p>Controlla la pelle mentre attenui. Il viso dovrebbe sembrare naturale e morbido, non grigio e senza vita: fermati prima che i colori spariscano del tutto.</p>\n<p>Attenuare va bene per matrimoni, ritratti e belle arti, dove una tavolozza delicata sembra elegante. Una foto attenuata con colori morbidi sembra raffinata, mentre una pacchiana sembra rumorosa.</p>\n<p>Per un aspetto completamente desaturato, usa il preset Bianco e nero a −100%. L’immagine diventa in bianco e nero, e va bene per scene drammatiche e ritratti senza tempo.</p>\n<h2 id=\"converting-to-grayscale\">Convertire in bianco e nero in un clic</h2>\n<p>Clicca il preset Bianco e nero per togliere tutto il colore dalla foto in un solo passaggio. L’immagine diventa in bianco e nero, e restano solo luminosità e contrasto a sostenerla.</p>\n<p>Il bianco e nero va bene per scene drammatiche, architettura e fotografia di strada, dove forma e luce contano più del colore. Va bene anche per ritratti con espressioni forti.</p>\n<p>Dopo la conversione, controlla il contrasto. Una foto in bianco e nero ha spesso bisogno di una piccola spinta di contrasto, perché il colore sosteneva parte della profondità che ora non c’è più.</p>\n<p>Esporta le foto in bianco e nero in JPG con un’impostazione di alta qualità, o in PNG per il risultato più nitido. Il formato conta meno del contrasto, che definisce l’aspetto in bianco e nero.</p>\n<h2 id=\"fixing-skin-tones\">Sistemare i toni della pelle</h2>\n<p>La pelle è la cosa più difficile da saturare correttamente. Una piccola spinta può far sembrare sano un ritratto, ma una grande fa diventare la pelle arancione, rossa o gialla.</p>\n<p>Parti da un piccolo aumento, del 10-15%, per i ritratti. Controlla il viso: la pelle dovrebbe sembrare calda e naturale, non come se la persona fosse stata troppo a lungo al sole.</p>\n<p>Guarda guance e fronte, che mostrano per prime la saturazione eccessiva. Un viso con guance arancioni e fronte gialla è stato spinto troppo oltre.</p>\n<p>Se dopo la spinta la pelle sembra arancione, abbassa il cursore del 5% e controlla di nuovo. Piccole riduzioni spesso ripristinano il tono naturale senza far perdere il bagliore sano.</p>\n<h2 id=\"previewing\">Controllare l’anteprima prima di scaricare</h2>\n<p>Controlla sempre l’anteprima prima di scaricare. Verifica che i colori sembrino naturali, che nessuna zona sia diventata neon e che i toni della pelle siano caldi e non arancioni.</p>\n<p>Ingrandisci fogliame, cielo e pelle a dimensione intera. Sono le zone che mostrano per prime la saturazione eccessiva, e una piccola anteprima può nascondere il problema.</p>\n<p>Controlla la foto su un secondo schermo, se puoi. I colori sembrano diversi su schermi diversi, e un secondo controllo rileva sorprese prima che tu condivida l’immagine.</p>\n<p>Se un colore sembra artificiale, abbassa il cursore del 5% e controlla di nuovo. Piccole riduzioni spesso ripristinano l’aspetto naturale senza far perdere la vividezza.</p>\n<h2 id=\"choosing-export-format\">Scegliere il formato di esportazione</h2>\n<p>Scegli il JPG per le foto che vuoi condividere. Mantiene piccoli i file e funziona ovunque, e un’impostazione di alta qualità mantiene puliti i colori.</p>\n<p>Scegli il PNG per grafiche e adesivi con trasparenza. Il PNG è senza perdite, quindi i colori restano esatti, e conserva le zone invisibili.</p>\n<p>Scegli il WebP quando vuoi file piccoli con una buona qualità. Funziona bene per le immagini web, anche se alcuni sistemi più vecchi rifiutano ancora questo formato.</p>\n<p>Ricorda che il cursore della qualità si nasconde per il PNG, perché il PNG è senza perdite e non ha un’impostazione di qualità da regolare. È un comportamento normale, non un problema dello strumento.</p>\n<h2 id=\"adjusting-on-mobile\">Regolare la saturazione da telefono o tablet</h2>\n<p>Lo strumento funziona sui touchscreen, quindi puoi sistemare una foto spenta direttamente dal telefono che l’ha scattata. Caricala dalla galleria, trascina il cursore con il dito e scarica il risultato.</p>\n<p>Trascinare un cursore con il dito è meno preciso che con il mouse. Usa i preset rapidi per valori esatti, poi rifinisci con piccoli trascinamenti.</p>\n<p>Controlla l’anteprima a dimensione intera prima di scaricare. Una modifica di saturazione che sullo schermo piccolo del telefono sembra buona può risultare troppo forte se vista da un computer.</p>\n<p>I file scaricati finiscono nella solita cartella dei download. Da lì puoi condividere la foto modificata direttamente in un’app di chat, in un’email o in un post social.</p>\n<h2 id=\"troubleshooting\">Risolvere i problemi più comuni della saturazione</h2>\n<p>Se la foto sembra pacchiana, il cursore è troppo alto. Abbassalo a piccoli passi finché erba, cielo e pelle sembrano di nuovo naturali.</p>\n<p>Se dopo la spinta la foto è ancora spenta, l’originale potrebbe essere troppo piatto per essere salvato. Una foto scattata attraverso una nebbia fitta non può guadagnare colore che non è mai stato catturato.</p>\n<p>Se la pelle sembra arancione, abbassa la saturazione e controlla il viso a dimensione intera. Una piccola riduzione di solito ripristina il tono naturale.</p>\n<p>Se l’anteprima sembra diversa dal file scaricato, controlla il formato di esportazione e la qualità. Un’impostazione di bassa qualità JPG può spostare leggermente i colori, soprattutto nelle zone chiare.</p>\n<h2 id=\"saturation-plus-contrast\">Saturazione più contrasto: la coppia più comune</h2>\n<p>Una foto spenta e piatta ha bisogno di saturazione e contrasto insieme. Potenzia prima i colori, poi aggiungi contrasto per ripristinare la profondità.</p>\n<p>Usa lo strumento <a href=\"/it/regola-contrasto-immagine/\">Regola contrasto immagine</a> dopo aver saturato, quando l’immagine sembra vivida ma ancora piatta. Una piccola spinta di contrasto riporta ombre e luci.</p>\n<p>Fai i passaggi in ordine: prima la saturazione, poi il contrasto. Invertirli può rendere più difficile giudicare la modifica del colore, perché l’immagine è ancora piatta.</p>\n<p>Controlla i colori dopo ogni passaggio. Una spinta di contrasto rende i colori più ricchi a sua volta, quindi la saturazione potrebbe aver bisogno di una piccola riduzione dopo.</p>\n<h2 id=\"saturation-for-social\">Saturazione per i social</h2>\n<p>I feed social premiano le foto vivide e chiare. Una foto spenta viene fatta scorrere via, mentre una ben saturata ferma il pollice e merita un secondo sguardo.</p>\n<p>Potenzia le foto social un po’ più di quanto faresti per la stampa. Gli schermi variano nei colori, e una foto che sul tuo telefono sembra a posto può sembrare spenta su quello di qualcun altro.</p>\n<p>Mantieni la spinta naturale. Una foto spinta troppo oltre sembra artificiale, e chi ti segue capisce quando i colori non corrispondono alla scena.</p>\n<p>Prova la foto saturata alla dimensione del feed prima di pubblicarla. Una foto che a dimensione intera sembra buona può essere troppo spenta o troppo pacchiana in una piccola anteprima, quindi controlla prima di pubblicare.</p>\n<h2 id=\"saving-settings\">Salvare le impostazioni per la prossima volta</h2>\n<p>Annota il valore di saturazione che ha funzionato per una serie di foto simili. Una breve nota, per esempio «paesaggi +20%», ti evita di indovinare la prossima volta.</p>\n<p>Per una serie di foto scattate con la stessa luce, usa lo stesso valore per tutte. Un colore coerente in una serie sembra professionale, mentre valori misti sembrano casuali.</p>\n<p>Conserva i file originali. Un valore di saturazione che va bene per una foto potrebbe non andare bene per un’altra, e l’originale ti permette di provare un altro livello senza danni aggiuntivi.</p>\n<p>Rileggi le tue note ogni tanto. Man mano che la tua fotocamera e la tua illuminazione migliorano, i valori di saturazione di cui hai bisogno cambieranno, e le vecchie note possono trarti in inganno.</p>\n<h2 id=\"quick-tips\">Consigli rapidi per una saturazione migliore</h2>\n<p>Regola a piccoli passi. Una variazione del 5% alla volta ti dà controllo, mentre un salto grande può superare il valore giusto prima che tu te ne accorga.</p>\n<p>Controlla la pelle, non solo il paesaggio. Una spinta per il paesaggio che sembra buona sull’erba può far diventare arancioni le persone nella foto.</p>\n<p>Usa i preset come punto di partenza. Un preset ti dà un test veloce, e il cursore ti permette di rifinire da lì.</p>\n<p>Salva la foto originale senza modifiche. Una volta che una modifica di saturazione è stata fissata in un’esportazione, non si può più annullare da quel file.</p>\n<h2 id=\"saturation-for-sunset\">Regolare la saturazione di una foto al tramonto</h2>\n<p>Le foto al tramonto sono già colorate, quindi hanno bisogno solo di una piccola spinta. Un aumento di saturazione del 10-15% approfondisce arancioni e rosa senza far sembrare dipinto il cielo.</p>\n<p>Guarda la sfumatura del cielo mentre potenzi. Un cielo al tramonto dovrebbe sfumare dolcemente da arancione a rosa a blu, e una forte spinta può trasformare quella sfumatura in blocchi piatti di colore.</p>\n<p>Controlla il primo piano dopo la spinta. Un primo piano scuro con i colori potenziati può sembrare torbido, quindi schiariscilo leggermente prima se il tramonto è il soggetto principale.</p>\n<p>Per un tramonto sull’acqua, una spinta moderata esalta il riflesso senza renderlo pacchiano. L’acqua dovrebbe rispecchiare il cielo, non competere con esso.</p>\n<p>Per il confronto, leggi <a href=\"/it/blog/saturazione-vs-vividezza/\">Saturazione o vividezza: come modificare i colori in modo naturale</a>. Per la panoramica completa, leggi <a href=\"/it/blog/come-regolare-saturazione-immagine-guida-completa/\">Regolare la saturazione di un’immagine: guida completa</a>. Per dare un aspetto coerente a tutte le foto, prova lo strumento <a href=\"/it/filtri-immagine/\">Filtri immagine</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Come potenzio i colori di una foto dal telefono?","answer":"Apri lo strumento Regola saturazione immagine nel browser del telefono, carica la foto dalla galleria e trascina il cursore a destra con il dito. Usa un preset rapido per un valore esatto, controlla i toni della pelle e scarica il risultato."},{"question":"Quale valore di saturazione devo usare per una foto di paesaggio?","answer":"Parti da +20% e controlla il fogliame. I paesaggi hanno di solito bisogno del 20-30% per sembrare vividi. Fermati prima che l’erba diventi neon o il cielo sembri dipinto, e abbassa il cursore se i colori sembrano artificiali."},{"question":"Come trasformo una foto a colori in bianco e nero?","answer":"Clicca il preset Bianco e nero, che imposta la saturazione a −100% e toglie tutto il colore in un solo passaggio. Controlla dopo il contrasto, perché una foto in bianco e nero ha spesso bisogno di una piccola spinta di contrasto per sostituire la profondità che il colore sosteneva."},{"question":"Perché la mia foto di cibo sembra finta dopo aver potenziato la saturazione?","answer":"Il cursore è troppo alto, e questo rende i rossi innaturalmente luminosi e i verdi neon. Il cibo ha bisogno solo di una piccola spinta, del 10-20%. Abbassa il cursore finché il piatto sembra fresco e appetitoso e non di plastica."},{"question":"Devo regolare la saturazione prima o dopo il contrasto?","answer":"Prima la saturazione, poi il contrasto. Potenziare i colori cambia la sensazione dell’immagine, e il contrasto rifinisce dopo la profondità. Ricontrolla i colori dopo la modifica del contrasto, perché li rende più ricchi a sua volta."},{"question":"Posso annullare una modifica di saturazione dopo aver scaricato?","answer":"Non dal file scaricato, perché la modifica è fissata nell’esportazione. Conserva la foto originale, così puoi provare un altro livello di saturazione. Nello strumento, usa l’opzione di reset per tornare a zero prima di scaricare."}];
